63	.takeaway-list li::before { content: counter(takeaway); position: absolute; left: 16px; top: 16px; width: 28px; height: 28px; background: var(--accent); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.85rem; }
